  70:     let (send_found_password, receive_found_password): (SyncSender<String>, Receiver<String>) =
  71:         sync_channel(1);
  72: 
  73:     let (total_password_count, skipped) = match strategy {
  74:         GenPasswords {
  75:             charset,
  76:             min_password_len,
  77:             max_password_len,
  78:             starting_password,
  79:         } => {
  80:             let mut skip = 0;
  81:             let total =
  82:                 password_generator_count(charset.len(), *min_password_len, *max_password_len);
  83:             if let Some(starting_password) = starting_password {
  84:                 skip =
  85:                     password_count_already_generated(charset, *min_password_len, starting_password);
  86:             }
  87:             (total, skip)
  88:         }
  89:         PasswordFile(password_list_path) => {
  90:             let total = password_reader_count(password_list_path.clone())?;
  91:             progress_bar.println(format!(
  92:                 "Using passwords dictionary {password_list_path:?} with {total} candidates."
